openCalendarObj = null;
paramCalendarObj = null;
/**
 * @method
 * @name fn_openCalendar
 * @description desc
 * @param {string} obj desc
 * @param {string} isFuture desc
 * @param {string} chkBzCalnd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_openCalendar = function(obj, isFuture, chkBzCalnd) {
    scwin.openCalendarObj = obj;
    if (isFuture) {
        isLecrDipt = true;
    } else {
        isLecrDipt = false;
    }
    popUpYYYYMMDD(obj);
};
